const items = $input.all();

const profileItem = items.find(i => i.json && Object.prototype.hasOwnProperty.call(i.json, 'motivation_note'));
const eventItems = items.filter(i => i !== profileItem);

const simdiMs = Date.now() + 3 * 3600000;
const simdi_istanbul = new Date(simdiMs).toISOString().replace('Z', '+03:00');

const etkinlikler = eventItems.map(item => {
  const j = item.json;
  const summary = j.summary || 'İsimsiz Etkinlik';
  const start = (j.start && (j.start.dateTime || j.start.date)) || '';
  return `- ${summary} | Baslangic: ${start}`;
});

const etkinlik_listesi = etkinlikler.join('\n');
const toplam_is = eventItems.length;
const odul_notu = (profileItem && profileItem.json && profileItem.json.motivation_note) ? String(profileItem.json.motivation_note).trim() : '';

return [{ json: { etkinlik_listesi, toplam_is, simdi_istanbul, odul_notu } }];

